window.MR.segments={"_meta":{"captured":"2026-10-18","what_this_is":"19 named projects and buyers outside the eight sector tabs: lunar and in-space power, a launch site, district and process heat, a port, broadcast data centres, an Arctic outpost, university research reactors, and data-center, mining and shipping buyers.","method":"A search-seeded draft (data/research/2026-10-08-refresh/drafts/space-apps.json) rewritten against fetched pages by a second agent, then quote-checked offline. 19 of 23 distinct sources are cached and quote-checked offline; the rest sit on hosts that block scripts. The group is curated in that folder's integrate_segments.py.","groups":[{"id":"space","label":"Space and launch"},{"id":"heat","label":"Heat, water and industry"},{"id":"ports-sites","label":"Ports, broadcast and Arctic outposts"},{"id":"campuses","label":"Universities"},{"id":"compute-industry","label":"Data centers, mines and ships"}]},"segments":[{"id":"draco-nuclear-thermal","segment":"space propulsion","name":"DRACO nuclear thermal rocket (DARPA and NASA)","status":"cancelled","power_class":"nuclear thermal propulsion engine (thrust, not electric output)","timeline":"awarded July 2023 with a flight demo targeted for fiscal 2027; killed by DARPA, reported June 2025","sponsor":"DARPA, NASA","vendor":"Lockheed Martin (prime); BWXT Advanced Technologies (reactor)","what_it_says":"DARPA and NASA gave Lockheed Martin a $499 million deal in 2023 to build a nuclear thermal rocket, with a flight demonstration aimed at fiscal 2027. DARPA then ended the program in 2025 because, in its deputy director's account, the costs no longer matched the benefits as launch prices fell.","microreactor_read":"A propulsion engine is not a power plant, so no 1-20 MW block fits. The program ended on cost once launch prices fell.","sources":[{"label":"Breaking Defense — DARPA, NASA tap Lockheed Martin to design, build DRACO (2023)","url":"https://breakingdefense.com/2023/07/darpa-nasa-tap-lockheed-martin-to-design-build-draco-nuclear-rocket-for-deep-space-missions/","quote":"DARPA and NASA have jointly awarded Lockheed Martin a $499 million deal to design and build an experimental rocket using a nuclear thermal propulsion engine","status":"fetched"},{"label":"Breaking Defense — DARPA's DRACO nuclear propulsion project roars no more (2025)","url":"https://breakingdefense.com/2025/06/darpas-draco-nuclear-propulsion-project-roars-no-more/","quote":"was driven by an assessment that the costs no longer match the benefits","status":"fetched"}],"group":"space"},{"id":"jetson-intuitive-machines","segment":"spacecraft and lunar power systems","name":"AFRL JETSON and Intuitive Machines radioisotope Stirling power","status":"funded","power_class":"not published","timeline":"$33.7 million JETSON award announced September 2023; $8.2 million extension reported 2025-10-31; flight experiment on the International Space Station planned","sponsor":"U.S. Air Force Research Laboratory, Space Vehicles Directorate","vendor":"Intuitive Machines","what_it_says":"AFRL gave Intuitive Machines a $33.7 million contract in 2023 for the JETSON low-power system, then an $8.2 million extension in 2025 on top of $9.5 million from an earlier AFRL program. The money funds a Stirling power converter that turns radioisotope heat into electricity and has passed a preliminary design review.","microreactor_read":"No output is published here. Radioisotope units are far smaller than a 1-20 MW block, so this is a conversion-technology precedent, with no microreactor buyer in it.","sources":[{"label":"Military & Aerospace Electronics — Space Force picks Intuitive Machines for space nuclear power (2023)","url":"https://www.militaryaerospace.com/power/article/14301010/space-nuclear-power","quote":"announced a $33.7 million contract to Intuitive Machines in late September","status":"fetched"},{"label":"World Nuclear News — X-energy sister company contracted for in-space nuclear technology (2025)","url":"https://wnn.world-nuclear.org/articles/x-energy-sister-company-contracted-for-in-space-nuclear-technology","quote":"a USD8.2 million contract extension to develop next-generation nuclear power systems for spacecraft and lunar infrastructure","status":"fetched"}],"group":"space"},{"id":"nasa-doe-fsp-lunar","segment":"lunar surface power","name":"NASA and DOE fission surface power for the Moon","status":"proposed","power_class":"at least 100 kWe","timeline":"NASA directive: launch-ready by first quarter of fiscal 2030; DOE-NASA agreement 2026-01-13","sponsor":"NASA, U.S. Department of Energy","what_it_says":"NASA says it will put a nuclear reactor on the Moon by the first quarter of fiscal year 2030, and has asked industry for a design of at least 100 kilowatts electric with a closed Brayton power cycle. Separately, DOE and NASA announced in January 2026 that they had signed an agreement to pursue the system.","microreactor_read":"At 100 kWe this is one to two orders of magnitude below the 1-20 MW band, so it is a design and supply-chain precedent (fuel, heat transfer, remote operation) and no buyer for a 1-20 MW block.","sources":[{"label":"NASA — NASA Seeks Industry Feedback on Fission Surface Power (2025)","url":"https://www.nasa.gov/centers-and-facilities/glenn/nasa-seeks-industry-feedback-on-fission-surface-power/","quote":"NASA will work with industry to design a fission surface power system that would provide at least 100 kilowatts of electrical power","status":"fetched"},{"label":"U.S. Department of Energy — DOE and NASA fission surface power announcement (2026)","url":"https://www.energy.gov/node/4855740","quote":"DOE and NASA anticipate deploying a fission surface power system capable of producing safe, efficient, and plentiful electrical power","status":"fetched"}],"group":"space"},{"id":"starbase-spaceport","segment":"launch sites and spaceports","name":"SpaceX Starbase, Boca Chica, Texas","status":"proposed","power_class":"250-megawatt gas-fired power station (2021 proposal)","timeline":"proposed in the FAA draft environmental assessment, September 2021; solar expansion reported May 2022","sponsor":"SpaceX","what_it_says":"The FAA's 2021 draft environmental assessment for Starship described a new 250-megawatt gas-fired power station at Starbase. By May 2022 SpaceX already ran a natural gas power plant on site, plus a solar farm that was being enlarged by 1.7 acres.","microreactor_read":"A 250 MW plant is about twelve times the top of the 1-20 MW band, and the site already runs on gas and solar, so a microreactor would be one add-on block. Whether the 250 MW unit was built is not shown on these pages.","sources":[{"label":"TechCrunch — The mystery of Elon Musk's missing gas (2021)","url":"https://techcrunch.com/2021/10/08/the-mystery-of-elon-musks-missing-gas/","quote":"Much more gas will be needed for a new 250-megawatt gas-fired power station.","status":"fetched"},{"label":"CNBC — SpaceX is expanding the solar farm at its South Texas launch facility (2022)","url":"https://www.cnbc.com/2022/05/03/spacex-expanding-solar-farm-at-boca-chica-texas-launch-facility.html","quote":"It also operates a natural gas power plant in Boca Chica.","status":"fetched"}],"group":"space"},{"id":"westinghouse-evinci-lunar","segment":"lunar surface power","name":"Westinghouse eVinci space microreactor and Astrobotic LunaGrid","status":"funded","power_class":"40 kW class (scaled down from the 5 MWe eVinci)","timeline":"Phase 2 contract announced 2025-01-07; LunaGrid first operational target 2028 (stated June 2023)","sponsor":"NASA, U.S. Department of Energy (award via Idaho National Laboratory)","vendor":"Westinghouse; Astrobotic (LunaGrid)","what_it_says":"Westinghouse is scaling down its 5 MWe eVinci microreactor into a 40-kilowatt class system for the lunar surface, and in January 2025 it won a Phase 2 contract to keep developing it. In June 2023 Astrobotic said it wanted the first operational LunaGrid at the lunar south pole by 2028.","microreactor_read":"The 40 kW lunar unit is far below 1-20 MW, but the parent design is a 5 MWe terrestrial microreactor, so lunar work on heat pipes and fuel feeds the same product line.","sources":[{"label":"World Nuclear News — Westinghouse, Astrobotic team up on space projects (2023)","url":"https://wnn.world-nuclear.org/articles/westinghouse,-astrobotic-team-up-on-space-projects","quote":"Westinghouse is developing a scaled-down version of its 5-MWe eVinci microreactor","status":"fetched"},{"label":"Westinghouse — NASA-DOE contract to continue space microreactor development (2025)","url":"https://info.westinghousenuclear.com/news/westinghouse-awarded-nasa-doe-contract-to-continue-development-of-space-microreactor-concept","quote":"would provide up to 40 kilowatts of power","status":"fetched"}],"group":"space"},{"id":"inl-marvel-desalination","segment":"desalination","name":"INL MARVEL end-user experiments, including produced-water desalination","status":"proposed","power_class":"85 kWt or up to 20 kWe","timeline":"five end users selected December 2025; MARVEL expected operational by late 2027","sponsor":"U.S. Department of Energy","vendor":"Idaho National Laboratory (MARVEL); Shepherd Power, NOV and ConocoPhillips (desalination team)","what_it_says":"In December 2025 INL picked five teams to run experiments on MARVEL, a sodium-potassium-cooled test microreactor producing 85 kWt or up to 20 kWe. Shepherd Power, NOV and ConocoPhillips propose a pilot-scale desalination project that uses the reactor's heat to treat oil and gas produced water.","microreactor_read":"MARVEL is one to two orders of magnitude smaller than a 1-20 MW block, so this tests the desalination hookup, not a buyer. A real produced-water plant would need a full-size unit, and no power price is published.","sources":[{"label":"Nuclear Engineering International — INL microreactor selects debut users (2025)","url":"https://www.neimagazine.com/?p=100744","quote":"Shepherd Power, NOV and ConocoPhillips, which propose leveraging MARVEL for a pilot-scale desalination project using nuclear-generated process heat","status":"fetched"}],"group":"heat"},{"id":"microreactor-ammonia-hydrogen","segment":"hydrogen and ammonia production","name":"5 MWe microreactor for ammonia from biomass (Nuclear Technology study)","status":"studied","power_class":"5 MWe","timeline":"paper published April 2026; no project announced","sponsor":"academic study","what_it_says":"A study published in Nuclear Technology in April 2026 costs ammonia made from corn stover, wheat straw or wood, with a 5 MWe nuclear microreactor supplying power and process heat to the Haber-Bosch process. It finds the cost depends strongly on microreactor capital cost and learning rate, and that the route is substantially cheaper than electrolysis plus Haber-Bosch.","microreactor_read":"A 5 MWe block is inside the 1-20 MW band and the paper treats it as the energy source. It is a paper study, with no site, buyer or ammonia price given on the page.","sources":[{"label":"American Nuclear Society — Technoeconomic Assessment of Ammonia Production from Biomass with Nuclear Microreactors (2026)","url":"https://www.ans.org/pubs/journals/nt/article-60263/","quote":"integrating thermal-chemical biomass gasification with a 5-MW(electric) nuclear microreactor as the energy source within the H-B process","status":"fetched"}],"group":"heat"},{"id":"microreactor-cement-calciner","segment":"steel and cement process heat","name":"Penn State feasibility study of microreactor heat for cement calcination","status":"studied","power_class":"15 MWth","timeline":"research project; no deployment date","sponsor":"Penn State Architectural Engineering (research project)","what_it_says":"Penn State researchers say a single 15 MWth reactor can supply enough heat to replace the calciner burner in a 2,000 ton/day cement plant, because calcination at about 900 C is within current core designs. They note that cement makes up 8% of global CO2 from human activity, and that 70 to 80% of a plant's fuel goes to the kiln burner and the rest to the calciner.","microreactor_read":"The 15 MWth figure is heat, so it does not compare directly with the 1-20 MW electric band. It would replace only the calciner share, and the kiln burner still needs fuel. The page gives no heat price and no plant has committed.","sources":[{"label":"Penn State — Feasibility Study of Micro-Nuclear Reactor Thermal Output for Air Rotary Kilns in Portland Cement Clinker Manufacturing","url":"https://pure.psu.edu/en/projects/feasibility-study-of-micro-nuclear-reactor-thermal-output-for-air/","quote":"a single 15 MWth reactor can provide enough energy in the form of heat to replace the calciner burner in a 2000 ton/day cement plant","status":"fetched"}],"group":"heat"},{"id":"steady-energy-ldr50","segment":"district heating","name":"Steady Energy LDR-50 pilot with Helen, Helsinki","status":"funded","power_class":"50 MW thermal reactor; about 6 MW pilot heat output","timeline":"lease to 2028; first concrete poured 2026-02-12","sponsor":"Steady Energy (privately raised capital); Helen hosts","vendor":"Steady Energy","what_it_says":"Steady Energy poured first concrete on 12 February 2026 for a non-nuclear, full-scale pilot of its LDR-50 district heating reactor in the Salmisaari B turbine hall in Helsinki. The pilot uses an electric element instead of fuel, outputs about 6 MW of heat to Helen's network, and has a EUR15-20 million budget. The reactor design is 50 MW thermal and runs at about 150C and below 10 bar.","microreactor_read":"The figures are thermal (50 MWth design, about 6 MW pilot heat), so they do not compare directly with the 1-20 MW electric band. Low pressure suits district heat. The pilot holds no fuel, so a licensed reactor is a later step.","sources":[{"label":"World Nuclear News — Construction of Steady Energy pilot plant begins (2026)","url":"https://wnn.world-nuclear.org/articles/construction-of-steady-energy-pilot-plant-begins","quote":"The first concrete for the pilot was poured on 12 February in the Salmisaari B turbine hall","status":"fetched"},{"label":"World Nuclear News — Pilot non-nuclear SMR plant to be built in Finnish coal-fired plant (2025)","url":"https://wnn.world-nuclear.org/articles/pilot-smr-plant-to-be-built-in-finnish-coal-fired-plant","quote":"The LDR-50 district heating SMR - with a thermal output of 50 MW - has been under development at VTT since 2020.","status":"fetched"}],"group":"heat"},{"id":"arctic-microreactor-canada","segment":"Arctic and defence outposts","name":"Canadian Strategic Missions Corporation Arctic microreactor","status":"funded","power_class":"not stated","timeline":"$4.5 million award reported 2026-07-23; company target of fleet-scale deployment by 2030","sponsor":"FedDev Ontario (Government of Canada)","vendor":"Canadian Strategic Missions Corporation","what_it_says":"FedDev Ontario awarded Canadian Strategic Missions Corporation $4.5 million to fund detailed design and a fuelled demonstration of its microreactor for the Arctic, part of a $40.5 million package split among 23 organisations. Canada's Department of National Defence has trouble supplying diesel to remote northern outposts.","microreactor_read":"No reactor size is published, so fit to the 1-20 MW band cannot be confirmed. The buyer is defence-led and diesel is the displaced fuel. The money funds design and a demonstration.","sources":[{"label":"SpaceQ — CSMC secures $4.5 million federal investment for Arctic microreactor development (2026)","url":"https://spaceq.ca/csmc-secures-4-5-million-federal-investment-for-arctic-microreactor-development/","quote":"has been awarded a $4.5 million investment from the Federal Economic Development Agency for Southern Ontario","status":"fetched"}],"group":"ports-sites"},{"id":"last-energy-london-gateway","segment":"ports and cold-chain logistics","name":"Last Energy PWR-20 and DP World London Gateway","status":"proposed","power_class":"20 MWe","timeline":"MOU signed 2025-09-15; aim to begin operations in 2030","sponsor":"DP World","vendor":"Last Energy","what_it_says":"Last Energy and DP World signed a memorandum of understanding for a PWR-20 microreactor at London Gateway to supply 20 MWe to the logistics hub, with extra output exported to the grid. The deal is described as a 80 million pound, subsidy-free investment in Last Energy's first unit, supporting DP World's 1 billion pound port expansion. London Gateway handles more than 50 per cent of the UK's deep-sea temperature-controlled imports.","microreactor_read":"20 MWe is the top of the 1-20 MW band and the load is a port with cold stores, so a block fits on size. An MOU is not a purchase agreement, and no power price is published.","sources":[{"label":"Last Energy — Last Energy Partners With DP World To Bring Micro-Nuclear Power To London Gateway (2025)","url":"https://www.lastenergy.com/news-press/last-energy-partners-with-dp-world-to-bring-micro-nuclear-power-to-london-gateway","quote":"A proposed PWR-20 microreactor would supply London Gateway with 20 MWe of clean, reliable electricity to power the logistics hub, with additional capacity exported to the grid.","status":"fetched"},{"label":"Nuclear Engineering International — London Gateway to host microreactor (2025)","url":"https://www.neimagazine.com/news/london-gateway-to-host-microreactor/","quote":"handling a wide range of cargoes including more than 50 per cent of the","status":"fetched"}],"group":"ports-sites"},{"id":"terra-innovatum-waiken-broadcast","segment":"telecom and broadcast data centres","name":"Terra Innovatum and Waiken ILW letter of intent for DIRECTV Latin America and SKY Brasil","status":"proposed","power_class":"up to 8 MWe (about 1 MWe per SOLO unit)","timeline":"letter of intent reported 2026-07-21; no construction timetable","sponsor":"Waiken ILW","vendor":"Terra Innovatum","what_it_says":"Terra Innovatum signed a commercial letter of intent with Waiken ILW for up to 8 MWe of behind-the-meter nuclear capacity at broadcasting data centres in Argentina and Brazil. Each SOLO unit is about 1 MWe, so the deal could mean up to eight modules, and the companies have not disclosed unit count, price or schedule.","microreactor_read":"Eight 1 MWe units sit inside the 1-20 MW band and the load is continuous communications equipment. The letter of intent does not authorise construction, and SOLO is still in pre-application with the U.S. NRC.","sources":[{"label":"eeNews Europe — Terra Innovatum plans SOLO microreactors for broadcasters (2026)","url":"https://www.eenewseurope.com/en/terra-innovatum-solo-microreactors-broadcasters/","quote":"Terra Innovatum Global has signed a commercial letter of intent with Waiken ILW covering up to 8 MWe of behind-the-meter nuclear generating capacity","status":"fetched"}],"group":"ports-sites"},{"id":"penn-state-evinci","segment":"universities","name":"Penn State and Westinghouse eVinci research reactor","status":"proposed","power_class":"size not stated on the cited page (parent eVinci design: 5 MWe)","timeline":"Penn State announced its letter of intent to the NRC on 2025-02-28","sponsor":"Penn State University","vendor":"Westinghouse","what_it_says":"Penn State announced on 28 February 2025 that it submitted a letter of intent to the NRC to host and operate a Westinghouse eVinci reactor on its University Park campus. eVinci is a HALEU TRISO-fueled sodium heat-pipe reactor, and Westinghouse describes its parent design as 5 MWe.","microreactor_read":"This is a research reactor, and the Deals tab lists it at 15 MWt. Only a letter of intent has been filed, and the page gives no campus load or heat price.","sources":[{"label":"American Nuclear Society — Penn State and Westinghouse make eVinci microreactor plan official (2025)","url":"https://www.ans.org/news/author-nnstaff/step-1741284029/","quote":"Penn State has announced that it submitted a letter of intent to host and operate an eVinci reactor to the Nuclear Regulatory Commission on February 28","status":"fetched"},{"label":"World Nuclear News — Westinghouse, Astrobotic team up on space projects (2023)","url":"https://wnn.world-nuclear.org/articles/westinghouse,-astrobotic-team-up-on-space-projects","quote":"Westinghouse is developing a scaled-down version of its 5-MWe eVinci microreactor","status":"fetched"}],"group":"campuses"},{"id":"tamu-rellis-aalo","segment":"universities","name":"Texas A&M RELLIS Energy Proving Ground, including Aalo Atomics","status":"proposed","power_class":"Aalo unit 30 MWth; site projected above 1 GW combined across developers","timeline":"agreements announced 2025-02-05; first reactors aimed within five years","sponsor":"Texas A&M University System","vendor":"Aalo Atomics, Kairos Power, Natura Resources, Terrestrial Energy","what_it_says":"Four developers signed agreements in February 2025 to site reactors at the 2,400-acre RELLIS campus in Bryan, Texas, with an Early Site Permit application already started and a combined output above one gigawatt projected. Aalo Atomics is the microreactor entrant and is aiming to develop a 30 MWth sodium-cooled unit.","microreactor_read":"Aalo's 30 MWth is heat, so it does not compare directly with the 1-20 MW electric band. The campus is a siting and permitting venue, and no power buyer or price is named.","sources":[{"label":"World Nuclear News — Four SMR developers aim to build reactors at Texas A&M University site (2025)","url":"https://wnn.world-nuclear.org/articles/four-smr-developers-aim-to-build-reactors-at-texas-am-university-site","quote":"Aalo Atomics is aiming to develop a 30 MWth sodium-cooled microreactor within the next few years.","status":"fetched"}],"group":"campuses"},{"id":"uiuc-kronos-mmr","segment":"universities","name":"University of Illinois Urbana-Champaign and Nano Nuclear Kronos MMR","status":"proposed","power_class":"up to 15 MWe (45 MWt) per unit","timeline":"construction permit application submitted to the NRC, reported 2026-04-02; project first announced 2021","sponsor":"University of Illinois Urbana-Champaign","vendor":"Nano Nuclear Energy","what_it_says":"UIUC and Nano Nuclear submitted a construction permit application to the NRC for a Kronos micro modular reactor on 31 March 2026, the first step of two-part Part 50 licensing for a research and test reactor. Each Kronos unit is designed for up to 15 MWe (45 MWt), and the 2021 plan was to re-power part of the coal-fired Abbott power station with it.","microreactor_read":"15 MWe is inside the 1-20 MW band and the host is a campus with a coal plant to displace. It is licensed as a research and test reactor, so campus power is secondary to training and research, and no power price is published.","sources":[{"label":"American Nuclear Society — UIUC submits MMR construction permit application (2026)","url":"https://www.ans.org/news/2026-04-02/article-7904/","quote":"Each TRISO-fueled and helium-cooled unit is designed to produce up to 15 MWe (45 MWt)","status":"fetched"},{"label":"World Nuclear News — US university plans to build microreactor (2021)","url":"https://world-nuclear-news.org/Articles/US-university-announces-plans-to-build-microreacto","quote":"The university plans to re-power partially its coal-fired Abbott power station","status":"fetched"},{"label":"World Nuclear News: Application lodged to build microreactor at US university (2026)","url":"https://world-nuclear-news.org/articles/application-lodged-to-build-microreactor-at-us-university","quote":"was submitted on 31 March by The Grainger College of Engineering","status":"fetched"}],"group":"campuses"},{"id":"uvation-data-center-pilot","segment":"data centers behind the meter","name":"Terra Innovatum Global and Uvation 1 MWe data-center pilot","status":"proposed","power_class":"1 MWe pilot, with a strategic option to scale up to 100 MWe","timeline":"letter of intent signed 2025-11-20","sponsor":"Uvation (private AI and modular data-center developer)","vendor":"Terra Innovatum (SOLO micro-modular reactor)","what_it_says":"Terra Innovatum Global and Uvation signed a letter of intent on 20 November 2025 to launch a 1 MWe pilot program with a strategic option to scale up to 100 MWe. The release says the expansion would run across multiple sites, with potentially several megawatt-scale installations in the US. It does not name a site and does not say whether the agreement is binding.","microreactor_read":"A 1 MWe pilot sits below the 1-20 MW band, and the 100 MWe option would sit at its top end only if built as several units. Only a letter of intent is public, and no power price is published.","sources":[{"label":"Stock Titan — Terra Innovatum Global and Uvation sign strategic 1 MWe pilot deployment (2025)","url":"https://www.stocktitan.net/news/NKLR/terra-innovatum-global-and-uvation-sign-strategic-1-m-we-pilot-mpat8agz6woy.html","quote":"launch a 1 MWe pilot program with a strategic option to scale up to 100 MWe","status":"fetched"},{"label":"Finviz — Terra Innovatum Global and Uvation sign strategic 1 MWe pilot deployment (2025)","url":"https://finviz.com/news/234834/terra-innovatum-global-and-uvation-sign-strategic-1-mwe-pilot-deployment-with-100-mwe-expansion-option-to-support-next-generation-ai-and-modular-data-center-growth","quote":"to launch a 1 MWe pilot program with a strategic option to scale up to 100 MWe","status":"fetched"}],"group":"compute-industry"},{"id":"tata-green-river-soda-ash","segment":"mining and mineral processing","name":"Tata Chemicals Soda Ash Partners, Green River trona site, with BWXT BANR","status":"proposed","power_class":"up to 8 BANR units at 50 MWt each (thermal)","timeline":"letter of intent signed by 2024-12-17; deployment aimed for the early 2030s","sponsor":"Tata Chemicals Soda Ash Partners","vendor":"BWXT Advanced Technologies (BANR)","what_it_says":"Tata Chemicals' soda ash subsidiary signed a letter of intent with BWXT Advanced Technologies to conditionally purchase up to eight BANR microreactors at its Green River, Wyoming soda ash site, which has an underground trona mine and a surface refining plant. BANR is a 50 MWt high-temperature gas microreactor (thermal rating only). The partners will set a schedule for deployment by the early 2030s.","microreactor_read":"The 50 MWt rating is thermal, so it does not map directly to the 1-20 MW electric band. The site uses purchased grid power plus its own coal and gas boilers for steam, so the displaced fuel is boiler fuel and purchased power. The letter of intent is conditional and sets no price.","sources":[{"label":"World Nuclear News — Tata, BWXT to explore microreactor use at Wyoming site (2024)","url":"https://world-nuclear-news.org/articles/tata-bwxt-to-explore-microreactor-use-at-wyoming-site","quote":"signed a letter of intent with BWXT Advanced Technologies LLC","status":"fetched"},{"label":"Sweetwater Now — Tata Chemicals Announces Letter of Intent to Explore Deployment of Nuclear Microreactors (2024)","url":"https://www.sweetwaternow.com/tata-chemicals-announces-letter-of-intent-to-explore-deployment-of-nuclear-microreactors/","quote":"signed a letter of intent to explore development of up to eight microreactors in the Green River area","status":"fetched"}],"group":"compute-industry"},{"id":"deep-fission-endeavour-data-centers","segment":"data centers behind the meter","name":"Deep Fission and Endeavour, 2 GW for data centers","status":"proposed","power_class":"15 MWe per borehole reactor; 2 GW total commitment","timeline":"strategic partnership announced 2025-01-08; first reactors expected to be operational in 2029","sponsor":"Endeavour (data-center developer)","vendor":"Deep Fission (borehole pressurised water reactor)","what_it_says":"Deep Fission and Endeavour committed to co-develop 2 GW of nuclear energy to power Endeavour's expanding portfolio of data centers, announced 8 January 2025. Deep Fission aims to place 15 MWe pressurised water reactors about one mile underground in a borehole. The first reactors are expected to be operational in 2029.","microreactor_read":"A 15 MWe unit fits the 1-20 MW band, but 2 GW is a portfolio commitment, not an order for units. The article does not say whether the partnership is binding, and no power price is published.","sources":[{"label":"World Nuclear News — Deep Fission and Endeavour announce strategic partnership (2025)","url":"https://www.world-nuclear-news.org/articles/deep-fission-and-endeavour-announce-strategic-partnership","quote":"committed to co-develop 2 GW of nuclear energy to power Endeavour's expanding portfolio of data centres","status":"fetched"},{"label":"TechCrunch — Nuclear startup Deep Fission plans to bury micro reactors to power data centers (2025)","url":"https://techcrunch.com/2025/01/07/nuclear-startup-deep-fission-plans-to-bury-micro-reactors-to-power-data-centers","quote":"signed a deal on Tuesday with data center developer Endeavour","status":"fetched"}],"group":"compute-industry"},{"id":"crowley-bwxt-nuclear-ship","segment":"maritime and shipping","name":"Crowley and BWXT nuclear power generation vessel concept","status":"studied","power_class":"modular reactor between 5 and 50 MW (per the announcement; electric or thermal not specified)","timeline":"memorandum of understanding announced 2023-09-20; design concept only","sponsor":"none named; the companies have no customer yet","vendor":"BWXT Advanced Technologies; Crowley (ship design)","what_it_says":"Crowley and BWXT Advanced Technologies signed a memorandum of understanding on 20 September 2023 to design a shallow-draft ship carrying a modular reactor between 5 and 50 megawatts. The ship would deliver power to shore for military bases in remote island locations and backup utility grids after disasters. Per a Jacksonville Business Journal report, the companies have no customer for the ship yet.","microreactor_read":"The 5-50 MW range overlaps the 1-20 MW band at its low end. This is a design concept with no buyer, no price and no site, so it is a segment signal rather than a deal.","sources":[{"label":"Ocean News — Crowley and BWXT debut nuclear power generation vessel concept (2023)","url":"https://oceannews.com/news/defense/crowley-and-bwxt-debut-nuclear-power-generation-vessel-concept/","quote":"carrying a modular reactor between 5 and 50 megawatts","status":"fetched"},{"label":"AJOT — Crowley, BWXT debut nuclear power generation vessel concept (2023)","url":"https://www.ajot.com/news/crowley-bwxt-debut-nuclear-power-generation-vessel-concept","quote":"carrying a modular reactor between 5 and 50 megawatts","status":"fetched"}],"group":"compute-industry"},{"id":"gridmarket-deployable-unb-framework","segment":"data centers behind the meter","name":"GridMarket and Deployable Energy Unity Nuclear Battery framework","status":"proposed","power_class":"approximately 1 megawatt electric (MWe) per unit; nearly 3 GW pipeline","timeline":"framework announced July 2026 (article dated 2026-07-08); target about 500 MW per year of deployment","vendor":"Deployable Energy (Unity Nuclear Battery)","what_it_says":"GridMarket and Deployable Energy announced a framework in July 2026 for a pipeline of nearly 3 GW of Unity Nuclear Battery microreactors. Each unit is about 1 MWe and fits in a 20-foot ISO container, with power integrated at the client's site to serve data centers, hyperscalers and industrial clients. The article does not say whether the framework is binding and says the pilot's definitive commercial terms remain to be specified.","microreactor_read":"A 1 MWe unit is at the small end of the 1-20 MW block range for a data-center load, but the framework names no site, load or price. It would count as a buyer deal only once it has a named first site, a binding instrument and a stated load.","sources":[{"label":"Energy News — GridMarket and Deployable Energy partner to deploy 3 GW of nuclear micro reactors (2026-07-08)","url":"https://energynews.pro/en/gridmarket-and-deployable-energy-partner-to-deploy-3-gw-of-nuclear-micro-reactors","quote":"approximately 1 megawatt electric (MWe)","status":"fetched"}],"group":"compute-industry"},{"id":"nuclea-new-mining-data-center","segment":"data centers behind the meter","name":"Nuclea Energy and New Mining Co. data-center MOU (Morpheus microreactor)","status":"proposed","power_class":"3.5-50 MWe per Morpheus unit (design range); first phase about 30 MWe of load","timeline":"MOU announced 2026-08-06; phased engineering study, no construction date","sponsor":"New Mining Co.","vendor":"Nuclea Energy","what_it_says":"Nuclea Energy and New Mining Co. signed a non-binding MOU on 2026-08-06 to study a behind-the-meter Morpheus microreactor for New Mining's data centers. The first phase covers engineering for New Mining's current operational data-center load of about 30 MWe, with expansion toward up to 100 MWe. The MOU is not a power purchase agreement.","microreactor_read":"The 3.5-50 MWe Morpheus design range includes a 1-20 MW block, but this is a design-stage MOU with no commercial unit, and it sets no supply price.","sources":[{"label":"StockTitan — Mangoceuticals merger partner Nuclea Energy signs MOU with New Mining Co. (2026-08-06)","url":"https://www.stocktitan.net/news/MGRX/mangoceuticals-merger-partner-nuclea-energy-inc-signs-mou-with-new-pwe91rkvk7ah.html","quote":"The MOU is non-binding and does not constitute a power purchase agreement","status":"fetched"}],"group":"compute-industry"},{"id":"oklo-wyoming-hyperscale-aspen-mountain","segment":"data centers behind the meter","name":"Oklo and Wyoming Hyperscale, Aspen Mountain data-center campus (letter of intent)","status":"proposed","power_class":"100 MW of carbon-free power (letter of intent)","timeline":"letter of intent announced May 2024 (ANS article dated 2024-05-29); 20-year power purchase agreement proposed","sponsor":"Wyoming Hyperscale","vendor":"Oklo","what_it_says":"Oklo and Wyoming Hyperscale signed a nonbinding letter of intent to supply 100 MW of carbon-free power for a 20-year power purchase agreement. The data center is planned for Aspen Mountain, a remote site southeast of Evanston, Wyoming. The source gives no price.","microreactor_read":"100 MW is more than one 1-20 MW block, so it would take several units. The letter of intent is non-binding, and no price is published in the source.","sources":[{"label":"American Nuclear Society — Oklo, Wyoming Hyperscale partner for data center energy (2024-05-29)","url":"https://www.ans.org/news/article-6080/oklo-wyoming-hyperscale-partner-for-data-center-energy/","quote":"signed a nonbinding letter of intent to provide 100 megawatts of carbon-free energy for a 20-year power purchase agreement","status":"fetched"}],"group":"compute-industry"},{"id":"radiant-idaho-strategic-mine-pilot","segment":"mining and mineral processing","name":"Idaho Strategic Resources and Radiant Kaleidos (Frontier pilot)","status":"proposed","power_class":"1 MWe per Kaleidos unit (1.9 MWt heat)","timeline":"non-binding MOU announced 2024-05-08; the release names no mine load and no construction date","sponsor":"Idaho Strategic Resources","vendor":"Radiant Industries","what_it_says":"Idaho Strategic Resources and Radiant Industries signed a non-binding MOU on 2024-05-08. It sets a path for the two companies to operate one or more of the first five Frontier Kaleidos units at a viable Idaho Strategic site. Kaleidos can output 1 MWe electric and 1.9 MWt of heat.","microreactor_read":"1 MWe sits at the bottom of the 1-20 MW block, so one unit would cover only a small share of a working mine's load. The MOU is non-binding and the release gives no mine load or price.","sources":[{"label":"Idaho Strategic Resources — Idaho Strategic announces memorandum of understanding with Radiant Industries Frontier Program (2024-05-08)","url":"https://webdisclosure.com/press-release/idaho-strategic-resources-inc-nasdaq-idr-idaho-strategic-announces-memorandum-of-understanding-with-radiant-industries-frontier-program-Gdjhn46QKqH","quote":"Kaleidos can output 1 MWe electric and 1.9 MWt of heat","status":"fetched"}],"group":"compute-industry"},{"id":"ngl-natura-produced-water-2026-02-04","segment":"desalination","name":"NGL Energy Partners and Natura Resources: produced-water desalination with a molten salt reactor","status":"proposed","power_class":"100 MW molten salt reactor (electric or thermal basis not stated)","timeline":"agreement announced 4 February 2026; no deployment date given","sponsor":"NGL Energy Partners (oilfield water treatment)","vendor":"Natura Resources","what_it_says":"Natura Resources and NGL Energy Partners agreed to look at pairing Natura's 100 MW molten salt reactor with NGL's produced-water treatment and desalination. The source says the two will collaborate in seeking opportunities and does not say the agreement is binding or give a site. Natura's produced-water work began in 2025 with Texas Tech and Abilene Christian University, which aims to treat produced water from oil and gas operations for beneficial use.","microreactor_read":"A 100 MW reactor is about five times the top of the 1-20 MW band, so it would take several blocks. The page gives no electric or thermal basis, no water volume, no power price and no site, so fit and price cannot be checked.","sources":[{"label":"World Nuclear News: Natura, NGL collaboration on water treatment (2026-02-04)","url":"https://wnn.world-nuclear.org/articles/natura-ngl-collaboration-on-water-treatment","quote":"Natura's 100 MW molten salt reactor (MSR)","status":"fetched"},{"label":"Texas Tech University: Texas Tech, ACU, Natura Resources announce path to deployment for nuclear reactor desalination of produced water (2025-07-03)","url":"https://www.ttu.edu/now/posts/2025/07/texas-tech-acu-natura-resources-announce-path-to-deployment-for-nuclear-reactor-desalination-of-produced-water.php","quote":"aiming to purify produced water from oil and gas operations for beneficial use.","status":"fetched"}],"group":"heat"}]};window.dispatchEvent(new CustomEvent('mr:segments'));
